{
  "name": "@abix5/opencode-beads",
  "version": "0.4.2",
  "description": "OpenCode plugin for the Beads (bd 1.0+) Dolt-powered issue tracker. Ships 26 typed beads_* tools covering the full bd surface — issues, dependencies, ready/blocked queues, comments, persistent memory, dolt push/pull, plus modern workflow primitives (formulas, molecules, wisps, human/timer/github gates). Forces JSON output, normalizes results, blocks raw `bd` via bash, and ships a /beads:wizard slash command that consults live beads docs through Context7 before proposing project setup options.",
  "type": "module",
  "main": "dist/index.js",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "assets"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/abix5/opencode-beads.git"
  },
  "bugs": {
    "url": "https://github.com/abix5/opencode-beads/issues"
  },
  "homepage": "https://github.com/abix5/opencode-beads#readme",
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "check": "tsc -p tsconfig.json --noEmit",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "beads",
    "bd",
    "dolt",
    "issues",
    "tracker",
    "workflow",
    "agent"
  ],
  "license": "MIT",
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.53"
  },
  "devDependencies": {
    "@types/node": "^22.13.10",
    "typescript": "^5.7.3"
  }
}
